'use client';

import React, { useCallback, useEffect, useState } from 'react';
import ReactFlow, {
    useNodesState,
    useEdgesState,
    addEdge,
    Connection,
    Edge,
    Controls,
    Background,
    MiniMap,
    ReactFlowProvider,
    Node,
    Position
} from 'reactflow';
import 'reactflow/dist/style.css';
import dagre from 'dagre';
import { SkillNode } from './SkillNode';
import { SKILL_TREE_DATA } from './data';
import { TOPIC_DATA } from './topic-data';
import { TopicModal } from './TopicModal';
import { getUserSkills, seedSkills } from '@/app/actions'; // Reuse existing actions for data fetching
import { Loader2 } from 'lucide-react';

const nodeTypes = {
    skill: SkillNode,
};

// Dagre Layouting Logic
const getLayoutedElements = (nodes: Node[], edges: Edge[]) => {
    const dagreGraph = new dagre.graphlib.Graph();
    dagreGraph.setDefaultEdgeLabel(() => ({}));

    const nodeWidth = 220;
    const nodeHeight = 100;

    dagreGraph.setGraph({ rankdir: 'TB', nodesep: 50, ranksep: 100 });

    nodes.forEach((node) => {
        dagreGraph.setNode(node.id, { width: nodeWidth, height: nodeHeight });
    });

    edges.forEach((edge) => {
        dagreGraph.setEdge(edge.source, edge.target);
    });

    dagre.layout(dagreGraph);

    nodes.forEach((node) => {
        const nodeWithPosition = dagreGraph.node(node.id);
        node.targetPosition = Position.Top;
        node.sourcePosition = Position.Bottom;

        // Shift slightly to center
        node.position = {
            x: nodeWithPosition.x - nodeWidth / 2,
            y: nodeWithPosition.y - nodeHeight / 2,
        };
    });

    return { nodes, edges };
};

export default function SkillTreeGraph() {
    const [nodes, setNodes, onNodesChange] = useNodesState([]);
    const [edges, setEdges, onEdgesChange] = useEdgesState([]);
    const [loading, setLoading] = useState(true);
    const [selectedTopic, setSelectedTopic] = useState<string | null>(null);

    const onConnect = useCallback(
        (params: Connection) => setEdges((eds) => addEdge({ ...params, type: 'smoothstep', animated: true }, eds)),
        [setEdges]
    );

    // Node Click Handler
    const onNodeClick = useCallback((event: React.MouseEvent, node: Node) => {
        if (node.data.unlocked) {
            setSelectedTopic(node.id);
        } else {
            // Shake/Lock feedback was handled in SkillNode internally for visuals,
            // but we can also do global toast here if needed.
        }
    }, []);

    useEffect(() => {
        const init = async () => {
            const handle = localStorage.getItem('cp-handle');
            // ... (rest of useEffect is unchanged)
            if (!handle) return;

            // Ensure skills in DB (if first time)
            await seedSkills();

            // Get live user progress
            // Note: getUserSkills currently returns a mapped list. 
            // We should use that to determine 'unlocked' / 'mastery'.
            const userSkills = await getUserSkills(handle);

            // Build Nodes from STATIC DATA but enriched with DYNAMIC USER DATA
            const initialNodes: Node[] = SKILL_TREE_DATA.map((skill) => {
                // Find matching progress
                const progress = userSkills.find((us: any) => us.slug === skill.id);
                // Fallback if not found (default locked/0)
                const unlocked = progress ? progress.unlocked : (skill.prerequisites.length === 0);
                const mastery = progress ? progress.mastery : 0;

                return {
                    id: skill.id,
                    type: 'skill',
                    data: {
                        label: skill.label,
                        iconName: skill.iconName,
                        xp: mastery, // Using mastery% as XP for now
                        xpRequired: skill.xpRequired,
                        unlocked: unlocked,
                        mastered: mastery >= 100
                    },
                    position: { x: 0, y: 0 } // Layout will fix this
                };
            });

            // Build Edges
            const initialEdges: Edge[] = [];
            SKILL_TREE_DATA.forEach(skill => {
                skill.prerequisites.forEach(parentId => {
                    const parent = initialNodes.find(n => n.id === parentId);
                    const isUnlocked = initialNodes.find(n => n.id === skill.id)?.data.unlocked;

                    if (parent) {
                        initialEdges.push({
                            id: `${parentId}-${skill.id}`,
                            source: parentId,
                            target: skill.id,
                            type: 'smoothstep',
                            animated: true,
                            style: { stroke: isUnlocked ? '#3b82f6' : '#3f3f46', strokeWidth: 2 }
                        });
                    }
                });
            });

            // Apply Dagre Layout
            const { nodes: layoutedNodes, edges: layoutedEdges } = getLayoutedElements(initialNodes, initialEdges);

            setNodes(layoutedNodes);
            setEdges(layoutedEdges);
            setLoading(false);
        };

        init();
    }, []);

    if (loading) {
        return (
            <div className="flex items-center justify-center h-[600px] w-full bg-zinc-950 rounded-xl border border-zinc-900">
                <Loader2 className="animate-spin text-blue-500" />
            </div>
        );
    }

    return (
        <div className="h-[75vh] w-full border border-zinc-800 rounded-xl bg-zinc-950 overflow-hidden relative shadow-2xl">
            <ReactFlow
                nodes={nodes}
                edges={edges}
                onNodesChange={onNodesChange}
                onEdgesChange={onEdgesChange}
                onConnect={onConnect}
                onNodeClick={onNodeClick}
                nodeTypes={nodeTypes}
                fitView
                minZoom={0.2}
                maxZoom={2}
                attributionPosition="bottom-right"
            >
                <Background color="#18181b" gap={25} size={1} />
                <Controls className="bg-zinc-800 border-zinc-700 text-white" />
                <MiniMap
                    nodeColor={(n) => {
                        if (n.data.mastered) return '#eab308';
                        if (n.data.unlocked) return '#3b82f6';
                        return '#3f3f46';
                    }}
                    style={{ background: '#09090b' }}
                    maskColor="rgba(0, 0, 0, 0.7)"
                    className="border border-zinc-800 rounded-lg"
                />
            </ReactFlow>

            {/* Modal Integration */}
            <TopicModal
                isOpen={!!selectedTopic}
                onClose={() => setSelectedTopic(null)}
                data={selectedTopic ? TOPIC_DATA[selectedTopic] : null}
            />

            {/* Overlay UI */}
            <div className="absolute top-6 left-6 pointer-events-none">
                <div className="bg-zinc-900/80 backdrop-blur border border-zinc-800 p-4 rounded-xl shadow-lg">
                    <h3 className="text-xl font-extrabold text-white flex items-center gap-2">
                        Tech Tree <span className="text-blue-500 text-xs px-2 py-0.5 bg-blue-500/10 rounded-full border border-blue-500/20">BETA</span>
                    </h3>
                    <p className="text-zinc-400 text-xs mt-1 max-w-[200px]">
                        Complete prerequisites to unlock advanced algorithms. Click unlocked nodes to practice.
                    </p>

                    <div className="flex gap-4 mt-3 text-[10px] font-bold uppercase tracking-widest text-zinc-500">
                        <div className="flex items-center gap-1"><div className="w-2 h-2 rounded-full bg-zinc-700"></div> Locked</div>
                        <div className="flex items-center gap-1"><div className="w-2 h-2 rounded-full bg-blue-500"></div> Unlocked</div>
                        <div className="flex items-center gap-1"><div className="w-2 h-2 rounded-full bg-yellow-500"></div> Mastered</div>
                    </div>
                </div>
            </div>
        </div>
    );
}

// Wrapper for Provider if needed (ReactFlow requires it if using useReactFlow hooks, but we aren't heavily using them yet)
export function SkillTreeWrapper() {
    return (
        <ReactFlowProvider>
            <SkillTreeGraph />
        </ReactFlowProvider>
    );
}
